import { test, expect } from '@playwright/test'
import { applyDiscount } from '../src/pricing'

// LAYER 1 · unit — owns the logic. Milliseconds, zero I/O, cannot flake.
test('applyDiscount takes 10% off the subtotal', () => {
  expect(applyDiscount(100, 0.1)).toBe(90)
  expect(applyDiscount(0, 0.1)).toBe(0)        // edge: empty cart
})

// LAYER 2 · contract — owns the API shape, not the arithmetic.
test('POST /api/checkout returns the agreed response shape', async ({ request }) => {
  const res = await request.post('/api/checkout', { data: { cart: 'c1', coupon: 'SAVE10' } })
  expect(res.status()).toBe(200)
  const body = await res.json()
  expect(body).toHaveProperty('total')          // shape, not value
  expect(typeof body.total).toBe('number')
})

// LAYER 3 · browser — owns ONLY the user-visible flow.
test('a shopper can reach checkout and see a total', async ({ page }) => {
  await page.goto('/cart')
  await page.getByRole('button', { name: 'Checkout' }).click()
  await expect(page.getByTestId('order-total')).toBeVisible()   // it renders — not what it equals
})

