import { test, expect, request } from '@playwright/test'
import { z } from 'zod'

// The contract: the SHAPE the checkout UI is built against.
const OrderConfirmation = z.object({
  order_id: z.string().uuid(),
  status: z.enum(['confirmed', 'pending', 'failed']),
  amount_cents: z.number().int().nonnegative(),
  currency: z.string().length(3),
  line_items: z.array(z.object({ sku: z.string(), qty: z.number().int().positive() })).min(1),
})

test('POST /orders honors the confirmation contract', async ({ playwright }) => {
  const api = await playwright.request.newContext({ baseURL: process.env.API_URL })
  const res = await api.post('/orders', { data: { sku: 'SKU-1', qty: 2 } })

  expect(res.status()).toBe(201)                    // status is part of the contract
  const body = await res.json()
  const parsed = OrderConfirmation.safeParse(body)  // assert the SHAPE, not just 200
  expect(parsed.success, parsed.error?.toString()).toBe(true)
})

