import { test as base } from '@playwright/test'

type Fixtures = { checkoutUser: { email: string }; authedPage: import('@playwright/test').Page }

export const test = base.extend<Fixtures>({
  // Per-test: a UNIQUE user so no two tests share cart/session state.
  checkoutUser: async ({}, use) => {
    const email = `buyer+${Date.now()}-${Math.random().toString(36).slice(2)}@test.dev`
    await seedUser(email)                 // create in DB via API, not the UI
    await use({ email })                  // hand state to the test
    await deleteUser(email)               // teardown ALWAYS runs, pass or fail
  },
  // Per-test: a freshly authenticated context — no reused storageState.
  authedPage: async ({ page, checkoutUser }, use) => {
    await apiLogin(page, checkoutUser.email)  // set session via API, skip the flaky UI login
    await use(page)
  },
})

