import { test as base, expect } from '@playwright/test'
import { createUser, deleteUser } from './api'

type Fixtures = { user: { email: string; id: string } }

export const test = base.extend<Fixtures>({
  user: async ({}, use, testInfo) => {
    // Unique key: run-id + worker index + test title -> no collisions
    const key = `${testInfo.workerIndex}-${Date.now()}-${testInfo.title}`
    const email = `qa+${key}@example.test`
    const created = await createUser({ email })
    await use(created)          // hand the isolated user to the test
    await deleteUser(created.id) // teardown: leave no residue for the next run
  },
})

export { expect }

