import { test, expect } from '@playwright/test'

test('completes checkout', async ({ page }) => {
  await page.goto('/cart')

  // BRITTLE (rejected): CSS hash + structural index
  // await page.locator('button.sc-a3f9x:nth-child(3)').click()
  // await page.waitForTimeout(2000) // flake: fixed sleep guesses render time

  // TIER 1 — the user's contract: role + accessible name
  await page.getByRole('button', { name: 'Place order' }).click()

  // TIER 2 — no clear role/label on the total, so an explicit handle
  const total = page.getByTestId('order-total')

  // Auto-waiting assertion: retries until the text appears — no sleep
  await expect(total).toHaveText('$42.00')
  await expect(page.getByRole('heading', { name: 'Order confirmed' })).toBeVisible()
})

