import { test, expect } from '@playwright/test'

test('confirms an order and shows the receipt', async ({ page }) => {
  await page.goto('/cart')

  // Brittle: CSS class can change; no wait for actionability
  // await page.click('.btn-primary')
  // await page.waitForTimeout(2000) // guesses the clock -> flake

  // Gold: role locator auto-waits for visible + stable + enabled
  await page.getByRole('button', { name: 'Place order' }).click()

  // Web-first assertion: polls the REAL post-condition until it holds
  await expect(page.getByRole('status')).toContainText('Order confirmed')
  await expect(page).toHaveURL(/\/receipt\/\d+/)
})

