accessibility-checks.code:
import { test, expect } from '@playwright/test'
import AxeBuilder from '@axe-core/playwright'

const BLOCKING = new Set(['serious', 'critical'])

test('checkout flow has no serious/critical a11y violations', async ({ page }, testInfo) => {
  await page.goto('/checkout')
  // getByRole = accessible-tree locator: if this fails, the control is invisible to AT
  await page.getByRole('button', { name: 'Place order' }).waitFor()

  const initial = await new AxeBuilder({ page })
    .withTags(['wcag2a', 'wcag2aa'])
    .analyze()

  // scan a STATE, not just a page load — the error state is where labels rot
  await page.getByRole('button', { name: 'Place order' }).click()
  const errorState = await new AxeBuilder({ page }).analyze()

  const blocking = [...initial.violations, ...errorState.violations]
    .filter((v) => BLOCKING.has(v.impact ?? ''))

  await testInfo.attach('axe-report', {
    body: JSON.stringify(blocking, null, 2),
    contentType: 'application/json',
  })

  expect(blocking, blocking.map((v) => `${v.id}: ${v.help}`).join('\n')).toEqual([])
})

