import { test, expect } from '@playwright/test'

const BUDGET_MS = 2500 // p95 confirmation budget; SLO is 3s, headroom left

test('checkout confirmation stays within budget', async ({ page }) => {
  await page.goto('/cart')
  await page.getByRole('button', { name: 'Checkout' }).click()
  await page.getByLabel('Card number').fill('4242424242424242')

  const start = Date.now()
  await page.getByRole('button', { name: 'Pay now' }).click()
  const heading = page.getByRole('heading', { name: 'Order confirmed' })
  await expect(heading).toBeVisible({ timeout: BUDGET_MS })
  const elapsed = Date.now() - start

  expect(elapsed, `confirmation took ${elapsed}ms`).toBeLessThan(BUDGET_MS)
})

