import { test, expect, request } from '@playwright/test'

const BASE = process.env.SMOKE_BASE_URL ?? 'https://staging.shop.example'

test('anon cannot read another user order (authz boundary)', async () => {
  const api = await request.newContext()
  const res = await api.get(`${BASE}/api/orders/ord_1001`) // no auth cookie
  expect([401, 403]).toContain(res.status())
  expect(await res.text()).not.toContain('line_items')
})

test('checkout page ships security headers', async () => {
  const api = await request.newContext()
  const res = await api.get(`${BASE}/checkout`)
  const h = res.headers()
  expect(h['strict-transport-security']).toBeDefined()
  expect(h['x-content-type-options']).toBe('nosniff')
  expect(h['content-security-policy']).toBeDefined()
})

test('order response never leaks payment secrets (exposure)', async () => {
  const api = await request.newContext({ storageState: 'auth/user.json' })
  const res = await api.get(`${BASE}/api/orders/mine/latest`)
  const body = await res.text()
  expect(body).not.toMatch(/\b\d{13,19}\b/)      // no raw PAN
  expect(body).not.toMatch(/"cvv"|"card_number"/i) // no secret fields
})

ci-quality-gates.code:
import { defineConfig, devices } from '@playwright/test'

export default defineConfig({
  // 1 retry ONLY to detect flake — not to launder red into green.
  retries: process.env.CI ? 1 : 0,
  // Every run emits inspectable evidence the gate can replay.
  use: {
    trace: 'retain-on-failure',
    screenshot: 'only-on-failure',
    video: 'retain-on-failure',
  },
  reporter: [
    ['html', { outputFolder: 'playwright-report' }],
    ['json', { outputFile: 'results/checkout.json' }],
  ],
  projects: [
    { name: 'chromium', use: { ...devices['Desktop Chrome'] } },
    // Accessibility scan runs as a first-class gated project.
    { name: 'a11y', testMatch: /.*\.a11y\.spec\.ts/ },
  ],
})

// gate.ts — the classifier the CI step runs after the suite.
// Rule: passed-on-retry counts as FLAKE (quarantine), never as PASS.
export function classify(r: TestResult) {
  if (r.status === 'passed' && r.retry > 0) return 'FLAKE'   // green only after retry
  if (r.title.includes('a11y') && r.status === 'failed') return 'A11Y_DEFECT'
  if (r.status === 'failed') return 'REGRESSION'
  return 'PASS'
}
